* { box-sizing: border-box; }
body { margin: 0; background: #f4f6f8; color: #182230; font: 16px/1.5 system-ui, sans-serif; }
.shell { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #e1e6ec; border-radius: 12px; box-shadow: 0 8px 24px #1822300c; }
h1 { margin: 0 0 28px; font-size: 2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.create-line, .project-row { display: flex; align-items: center; gap: 12px; }
input { flex: 1; min-width: 0; padding: 10px 12px; border: 1px solid #aeb8c4; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #245fc5; color: white; font: inherit; cursor: pointer; }
button:hover { background: #194b9f; }
.project-row { justify-content: space-between; padding: 16px 0; border-bottom: 1px solid #e6eaf0; }
#projects { margin-top: 20px; }
.alert { color: #b42318; margin: 10px 0; }
.back { margin-bottom: 24px; }
@media (max-width: 600px) { .shell { margin: 20px 12px; padding: 22px; } .create-line { align-items: stretch; flex-direction: column; } }

